(window.CLAVE_TEST=window.CLAVE_TEST||{})[21]=[{"a":"Artículo segundo R3","q":[{"i":"21-13","p":"Ley Orgánica 6/1984, reguladora del Procedimiento de «Habeas Corpus». Es competente para conocer la solicitud de «Habeas Corpus»:","o":["En primer lugar, el Juez de Instrucción del lugar en que se encuentre la persona privada de libertad","Si no constare, el del lugar en que se produzca la detención","En defecto de los anteriores, el del lugar donde se hayan tenido las últimas noticias sobre el paradero del detenido","Todas las opciones anteriores son correctas por su orden"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones anteriores son correctas por su orden</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"el del lugar en que se produzca la detención, y, en defecto de los anteriores, el del lugar donde se hayan tenido las últimas noticias sobre el paradero del detenido\"</span>Los tres criterios son sucesivos: lugar de privación de libertad, lugar de la detención y últimas noticias del paradero."},{"i":"21-30","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. Es competente para conocer la solicitud de Habeas Corpus, en primer lugar:","o":["El Juez de Instrucción del lugar en que se produzca la detención.","El Juez de Instrucción del lugar en que se encuentre la persona privada de libertad.","El Juez de Instrucción del lugar donde se hayan tenido las últimas noticias sobre el paradero del detenido.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Juez de Instrucción del lugar en que se encuentre la persona privada de libertad</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"el del lugar en que se produzca la detención, y, en defecto de los anteriores, el del lugar donde se hayan tenido las últimas noticias sobre el paradero del detenido\"</span>En primer lugar es competente el Juez del lugar donde se encuentra la persona privada de libertad; los otros dos criterios son subsidiarios."},{"i":"21-ia-1033","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. Si la detención obedece a la aplicación de la Ley Orgánica que desarrolla los supuestos previstos en la Constitución para la suspensión de derechos de personas vinculadas a bandas armadas o elementos terroristas, el procedimiento deberá seguirse ante:","o":["el Juez Central de Instrucción correspondiente.","el Juez de Instrucción del lugar en que se encuentre la persona privada de libertad.","el Juez de Vigilancia Penitenciaria correspondiente.","el Juez Central de lo Penal correspondiente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Juez Central de Instrucción correspondiente</mark></span><span class=\"ref-norma\">Art. 2 · Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"el procedimiento deberá seguirse ante el Juez Central de Instrucción correspondiente\"</span>En los supuestos de bandas armadas o terroristas el competente es el Juez Central de Instrucción."},{"i":"21-ia-1027","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. Principios inspiradores. En virtud de la generalidad, ningún particular o agente de la autoridad pueda sustraerse al control judicial de la legalidad de la detención de las personas sin que quepa en este sentido excepción de ningún género, ni siquiera en lo referente a la Autoridad:","o":["Gubernativa.","Penitenciaria.","Militar.","Administrativa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Militar</mark></span><span class=\"ref-norma\">Exposición de motivos · Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"ni siquiera en lo referente a la Autoridad Militar\"</span>La generalidad abarca incluso a la Autoridad Militar."},{"i":"21-ia-1034","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. En el ámbito de la Jurisdicción Militar será competente para conocer de la solicitud de «Habeas Corpus» el Juez Togado Militar de Instrucción constituido en la cabecera de la circunscripción jurisdiccional en la que:","o":["se encuentre el establecimiento penitenciario militar.","tenga su destino el detenido.","se cometió el presunto delito militar.","se efectuó la detención."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se efectuó la detención</mark></span><span class=\"ref-norma\">Art. 2 · Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"constituido en la cabecera de la circunscripción jurisdiccional en la que se efectuó la detención\"</span>El criterio es el lugar donde se efectuó la detención."},{"i":"21-86","p":"Ley Orgánica 6/1984, de 24 de Mayo, reguladora del procedimiento de «habeas corpus». En el ámbito de la Jurisdicción Militar será competente para conocer de la solicitud de «Habeas Corpus»:","o":["El Juez Togado Militar de instrucción constituido en la cabecera de la circunscripción jurisdiccional en la que se efectuó la detención.","El Juez Central de Instrucción.","El Juez Togado Militar de Instrucción constituido en la cabecera de la circunscripción jurisdiccional del lugar en que se encuentre la persona privada de libertad.","El Juez de Instrucción del lugar donde se produzca la detención."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Juez Togado Militar de instrucción constituido en la cabecera de la circunscripción jurisdiccional en la que se efectuó la detención</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"será competente para conocer de la solicitud de «Habeas Corpus» el Juez Togado Militar de Instrucción constituido en la cabecera de la circunscripción jurisdiccional en la que se efectuó la detención\"</span>El criterio militar es el lugar donde se efectuó la detención."},{"i":"21-131","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. Principios inspiradores del procedimiento de Habeas Corpus. En el ámbito de la Jurisdicción Militar será competente para conocer de la solicitud de Habeas Corpus:","o":["El Juez Central de Instrucción.","El Juez Central Militar de Instrucción.","El Juez Togado Militar de Instrucción.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Juez Togado Militar de Instrucción</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"será competente para conocer de la solicitud de «Habeas Corpus» el Juez Togado Militar de Instrucción\"</span>"}]},{"a":"Artículo quinto","q":[{"i":"21-35","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. La autoridad gubernativa, agente de la misma o funcionario público, estarán obligados respecto de la solicitud de «Habeas Corpus»:","o":["A ponerla inmediatamente en conocimiento del Juez competente.","A ponerla en conocimiento del Juez competente en un plazo máximo de doce horas.","A ponerla en conocimiento del Juez competente en un plazo máximo de veinticuatro horas.","A ponerla en conocimiento del Juez competente en un plazo máximo de cuarenta y ocho horas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A ponerla inmediatamente en conocimiento del Juez competente</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"estarán obligados a poner inmediatamente en conocimiento del Juez competente la solicitud de «Habeas Corpus», formulada por la persona privada de libertad que se encuentre bajo su custodia\"</span>No hay plazo de horas: la comunicación al Juez es inmediata."},{"i":"21-141","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del Procedimiento de Habeas Corpus. ¿Cuál es la obligación de la autoridad gubernativa, agente de la misma o funcionario público en relación con las solicitudes de \"Habeas Corpus\"?:","o":["Poner inmediatamente en conocimiento del Juez competente la solicitud.","Ignorar la solicitud y no informar al Juez.","Denegar la solicitud sin consultar al Juez.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Poner inmediatamente en conocimiento del Juez competente la solicitud</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"La autoridad gubernativa, agente de la misma o funcionario público, estarán obligados a poner inmediatamente en conocimiento del Juez competente la solicitud de «Habeas Corpus»\"</span>"},{"i":"21-ia-1040","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. Si la autoridad gubernativa, agente de la misma o funcionario público incumplieren la obligación de poner inmediatamente en conocimiento del Juez competente la solicitud de «Habeas Corpus», serán apercibidos por el Juez, sin perjuicio de las responsabilidades:","o":["penales y administrativas en que pudieran incurrir.","penales y disciplinarias en que pudieran incurrir.","civiles y disciplinarias en que pudieran incurrir.","disciplinarias, con exclusión de las penales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">penales y disciplinarias en que pudieran incurrir</mark></span><span class=\"ref-norma\">Art. 5 · Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"serán apercibidos por el Juez, sin perjuicio de las responsabilidades penales y disciplinarias en que pudieran incurrir\"</span>El apercibimiento es sin perjuicio de las responsabilidades penales y disciplinarias."}]},{"a":"Artículo sexto R5","q":[{"i":"21-201","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de «Habeas Corpus». Promovida la solicitud de «Habeas Corpus» el Juez examinará la concurrencia de los requisitos para su tramitación y dará traslado de la misma al:","o":["Ministerio de Defensa.","Ministerio Fiscal.","Ministerio de Justicia.","Ministerio del Interior."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Ministerio Fiscal</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"el Juez examinará la concurrencia de los requisitos para su tramitación y dará traslado de la misma al Ministerio Fiscal\"</span>"},{"i":"21-218","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento Habeas Corpus. Promovida la solicitud de «Habeas Corpus» el Juez examinará la concurrencia de los requisitos para su tramitación y dará traslado de la misma al ______. Seguidamente, mediante auto, acordará la incoación del procedimiento, o, en su caso, denegará la solicitud por ser ésta improcedente.","o":["Letrado de la Administración de Justicia.","Fiscal General.","Ministerio Fiscal.","Defensor del Pueblo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ministerio Fiscal</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"el Juez examinará la concurrencia de los requisitos para su tramitación y dará traslado de la misma al Ministerio Fiscal. Seguidamente, mediante auto, acordará la incoación del procedimiento\"</span>"},{"i":"21-31","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. Señale la incorrecta:","o":["El Juez deducirá testimonio de los particulares pertinentes para la persecución y castigo de los delitos que hayan podido cometerse por quienes hubieran ordenado la detención, o tenido bajo su custodia a la persona privada de libertad.","Promovida la solicitud de «Habeas Corpus» el Juez examinará la concurrencia de los requisitos para su tramitación, sin dar traslado de la misma al Ministerio Fiscal.","El procedimiento se iniciará por medio de escrito o comparecencia, no siendo preceptiva la intervención de Abogado ni de Procurador.","La autoridad gubernativa, agente de la misma o funcionario público, estarán obligados a poner inmediatamente en conocimiento del Juez competente la solicitud de «Habeas Corpus», formulada por la persona privada de libertad que se encuentre bajo su custodia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Promovida la solicitud de «Habeas Corpus» el Juez examinará la concurrencia de los requisitos para su tramitación, sin dar traslado de la misma al Ministerio Fiscal</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"Promovida la solicitud de «Habeas Corpus» el Juez examinará la concurrencia de los requisitos para su tramitación y dará traslado de la misma al Ministerio Fiscal\"</span>El Juez sí da traslado al Ministerio Fiscal (art. sexto); las demás opciones reproducen la ley."},{"i":"21-ia-1041","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. Promovida la solicitud de «Habeas Corpus» el Juez examinará la concurrencia de los requisitos para su tramitación y dará traslado de la misma al Ministerio Fiscal. Seguidamente, mediante auto, acordará la incoación del procedimiento, o, en su caso, denegará la solicitud por ser ésta improcedente. Dicho auto se notificará, en todo caso:","o":["al Ministerio Fiscal.","al Defensor del Pueblo.","a la autoridad bajo cuya custodia se halle el privado de libertad.","al Abogado del solicitante."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al Ministerio Fiscal</mark></span><span class=\"ref-norma\">Art. 6 · Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"Dicho auto se notificará, en todo caso, al Ministerio Fiscal\"</span>El auto de incoación o denegación se notifica en todo caso al Ministerio Fiscal."},{"i":"21-ia-1042","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. Contra la resolución que, en uno u otro caso, adopte el Juez sobre la incoación o la denegación de la solicitud de «Habeas Corpus»:","o":["cabrá recurso de reforma ante el mismo Juez.","cabrá recurso de apelación ante la Audiencia Provincial.","cabrá recurso de queja ante el Tribunal Superior de Justicia.","no cabrá recurso alguno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no cabrá recurso alguno</mark></span><span class=\"ref-norma\">Art. 6 · Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"Contra la resolución que en uno u otro caso se adopte\"</span>Contra la resolución (admitida a trámite o denegada) no cabrá recurso alguno. Ni la incoación ni la denegación admiten recurso alguno."}]},{"a":"Artículo séptimo","q":[{"i":"21-ia-1043","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. En el auto de incoación, el Juez ordenará a la autoridad a cuya disposición se halle la persona privada de libertad o a aquél en cuyo poder se encuentre, que la ponga de manifiesto ante él:","o":["en el plazo máximo de veinticuatro horas o se constituirá en el lugar donde aquélla se encuentre.","sin pretexto ni demora alguna, y en ningún caso se constituirá en el lugar donde aquélla se encuentre.","sin pretexto ni demora alguna o se constituirá en el lugar donde aquélla se encuentre.","previa audiencia del Ministerio Fiscal o se constituirá en el lugar donde aquélla se encuentre."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">sin pretexto ni demora alguna o se constituirá en el lugar donde aquélla se encuentre</mark></span><span class=\"ref-norma\">Art. 7 · Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"que la ponga de manifiesto ante él, sin pretexto ni demora alguna o se constituirá en el lugar donde aquélla se encuentre\"</span>Debe presentarla sin pretexto ni demora, o el Juez se constituye donde se encuentre."},{"i":"21-172","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del Procedimiento de Habeas Corpus. ¿Quiénes pueden instar el procedimiento de \"Habeas Corpus\"?","o":["El privado de libertad.","El Ministerio Fiscal.","El Defensor del Pueblo.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"Podrán instar el procedimiento de “Habeas Corpus” que esta ley establece: a) El privado de libertad, su cónyuge o persona unida por análoga relación de afectividad, descendientes, ascendientes, hermanos\"</span>"},{"i":"21-ia-1044","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. Antes de dictar resolución, el Juez oirá a la persona privada de libertad o, en su caso, a su representante legal y Abogado, si lo hubiera designado, así como al Ministerio Fiscal; acto seguido oirá:","o":["al Defensor del Pueblo y a la autoridad que hubiere ordenado o practicado la detención o internamiento.","en justificación de su proceder a la autoridad, agentes, funcionario público o representante de la institución o persona que hubiere ordenado o practicado la detención o internamiento.","en justificación de su proceder a la autoridad, agentes o funcionario público que hubieren practicado la detención, pero no a la persona que hubiere ordenado el internamiento, previo informe de la unidad policial competente.","a los testigos de la detención y al Letrado de la Administración de Justicia del Juzgado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en justificación de su proceder a la autoridad, agentes, funcionario público o representante de la institución o persona que hubiere ordenado o practicado la detención o internamiento</mark></span><span class=\"ref-norma\">Art. 7 · Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"acto seguido oirá en justificación de su proceder a la autoridad, agentes, funcionario público o representante de la institución o persona que hubiere ordenado o practicado la detención o internamiento\"</span>Después de oír al privado de libertad y al Fiscal, oye en justificación de su proceder a quien ordenó o practicó la detención."},{"i":"21-ia-1045","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. El Juez admitirá, si las estima pertinentes, las pruebas que aporten las personas a que se refiere el párrafo anterior y las que propongan que puedan practicarse:","o":["en el acto.","en el plazo de veinticuatro horas.","en la comparecencia posterior.","dentro de las cuarenta y ocho horas siguientes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en el acto</mark></span><span class=\"ref-norma\">Art. 7 · Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"las pruebas que aporten las personas a que se refiere el párrafo anterior y las que propongan que puedan practicarse en el acto\"</span>Se admiten las pruebas pertinentes que puedan practicarse en el acto."},{"i":"21-136","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. Desde que sea dictado el auto de incoación, los Jueces practicarán todas las actuaciones y dictarán la resolución que proceda en el plazo de:","o":["Siete horas.","Nueve horas.","Veinticuatro horas.","Treinta y seis horas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinticuatro horas</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"En el plazo de veinticuatro horas, contadas desde que sea dictado el auto de incoación, los Jueces practicarán todas las actuaciones a que se refiere este artículo y dictarán la resolución que proceda\"</span>"},{"i":"21-ia-1025","p":"Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus. Principios inspiradores. La ley orgánica se inspira en cuatro principios complementarios. El procedimiento judicial sumario y extraordinariamente rápido tiene que finalizar en __________:","o":["veinticuatro horas","cuarenta y ocho horas","setenta y dos horas","cinco días"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">veinticuatro horas</mark></span><span class=\"ref-norma\">Exposición de motivos · Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"procedimiento judicial sumario y extraordinariamente rápido, hasta el punto de que tiene que finalizar en veinticuatro horas\"</span>El primer principio es la agilidad: el procedimiento finaliza en veinticuatro horas."},{"i":"21-101","p":"Ley Orgánica 6/1984, de 24 de Mayo, reguladora del procedimiento de «habeas corpus». El procedimiento de hábeas corpus deberá resolverse:","o":["En el plazo de veinticuatro horas.","En el plazo de cuarenta y ocho horas.","En el plazo de setenta y dos horas.","En el plazo de cinco días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En el plazo de veinticuatro horas</mark></span><span class=\"ref-norma\">Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de Habeas Corpus</span><span class=\"ref-concepto\">\"En el plazo de veinticuatro horas, contadas desde que sea dictado el auto de incoación, los Jueces practicarán todas las actuaciones a que se refiere este artículo y dictarán la resolución que proceda\"</span>El plazo de 24 horas se cuenta desde el auto de incoación."}]},{"a":"Artículo 1 ✱ R9","q":[{"i":"21-19","p":"Ley Orgánica 19/1994, de Protección a testigos y peritos en causas criminales. Las medidas de protección previstas en esta Ley son aplicables:","o":["A quienes en calidad de testigos o peritos intervengan en procesos penales","A quienes en calidad de testigos o peritos intervengan en procesos judiciales","A quienes en calidad de testigos o peritos intervengan en procesos graves","A quienes en calidad de parte, testigos o peritos intervengan en procesos penales"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A quienes en calidad de testigos o peritos intervengan en procesos penales</mark></span><span class=\"ref-norma\">Art. 1 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"Las medidas de protección previstas en esta Ley son aplicables a quienes en calidad de testigos o peritos intervengan en procesos penales\"</span>"},{"i":"21-187","p":"Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales. ¿Cuál de las siguientes personas está incluida en la protección prevista por la Ley cuando interviene en procesos penales?","o":["Testigos.","Peritos.","A y B son correctas.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span><span class=\"ref-norma\">Art. 1 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"Las medidas de protección previstas en esta Ley son aplicables a quienes en calidad de testigos o peritos intervengan en procesos penales\"</span>"},{"i":"21-ia-1141","p":"Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales. La protección alcanza a quien pretenda ampararse en la Ley, a su cónyuge o persona a quien se halle ligado por análoga relación de afectividad o a sus:","o":["ascendientes, descendientes o hermanos.","ascendientes y descendientes hasta el segundo grado.","descendientes y hermanos, pero no a los ascendientes.","parientes hasta el cuarto grado de consanguinidad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">ascendientes, descendientes o hermanos</mark></span><span class=\"ref-norma\">Art. 1.2 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"su cónyuge o persona a quien se halle ligado por análoga relación de afectividad o sus ascendientes, descendientes o hermanos\"</span>Incluye cónyuge o pareja, ascendientes, descendientes o hermanos."},{"i":"21-ia-1140","p":"Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales. Para que sean de aplicación las disposiciones de la ley de protección a testigos y peritos será necesario que la autoridad judicial aprecie racionalmente un peligro __________ para la persona, libertad o bienes de quien pretenda ampararse en ella:","o":["inminente","grave","cierto","manifiesto"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">grave</mark></span><span class=\"ref-norma\">Art. 1.2 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"aprecie racionalmente un peligro grave para la persona, libertad o bienes de quien pretenda ampararse en ella\"</span>El peligro ha de ser grave y apreciado racionalmente por la autoridad judicial."}]},{"a":"Artículo 4 ✱ R10 R11 R12","q":[{"i":"21-ia-1150","p":"Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales. El órgano judicial competente para el enjuiciamiento, al revisar las medidas de protección, lo hará previa ponderación de los bienes jurídicos constitucionalmente protegidos, de los derechos fundamentales en conflicto y de:","o":["las circunstancias personales del procesado en relación con el proceso penal de que se trate, sin perjuicio de lo previsto en la normativa vigente.","el informe de la Policía Judicial sobre el grado de riesgo de los testigos y peritos.","las peticiones de las partes sobre la identidad de los testigos y peritos.","las circunstancias concurrentes en los testigos y peritos en relación con el proceso penal de que se trate."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las circunstancias concurrentes en los testigos y peritos en relación con el proceso penal de que se trate</mark></span><span class=\"ref-norma\">Art. 4.1 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"de las circunstancias concurrentes en los testigos y peritos en relación con el proceso penal de que se trate\"</span>Se ponderan también las circunstancias concurrentes en los testigos y peritos."},{"i":"21-ia-1149","p":"Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales. Recibidas las actuaciones, el órgano judicial competente para el enjuiciamiento de los hechos se pronunciará motivadamente sobre la procedencia de mantener, modificar o suprimir todas o algunas de las medidas de protección de los testigos y peritos adoptadas por:","o":["el Juez de Instrucción, así como si procede la adopción de otras nuevas.","el Ministerio Fiscal, así como si procede la adopción de otras nuevas, previo informe de la unidad policial competente.","la Policía Judicial, así como si procede la adopción de otras nuevas.","el Juez de Instrucción, sin que proceda la adopción de otras nuevas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Juez de Instrucción, así como si procede la adopción de otras nuevas</mark></span><span class=\"ref-norma\">Art. 4.1 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"las medidas de protección de los testigos y peritos adoptadas por el Juez de Instrucción, así como si procede la adopción de otras nuevas\"</span>El órgano de enjuiciamiento revisa las medidas del Juez de Instrucción y decide si adopta otras nuevas."},{"i":"21-191","p":"Ley Orgánica 19/1994, de 23 de diciembre, de protección a testigos y peritos en causas criminales. Las medidas adoptadas podrán ser objeto de recurso de:","o":["Reforma o súplica.","Apelación.","Queja.","Reposición."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Reforma o súplica</mark></span><span class=\"ref-norma\">Art. 4 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"Las medidas adoptadas podrán ser objeto de recurso de reforma o súplica\"</span>"},{"i":"21-239","p":"Ley Orgánica 19/1994, de 23 de diciembre, de protección a testigos y peritos en causas criminales. Las medidas adoptadas podrán ser objeto de:","o":["Recurso de reforma.","Recurso de súplica.","Recurso de repostación.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas</mark></span><span class=\"ref-norma\">Art. 4 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"Las medidas adoptadas podrán ser objeto de recurso de reforma o súplica\"</span>"},{"i":"21-ia-1151","p":"Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales. Si cualquiera de las partes solicitase motivadamente en su escrito de calificación provisional, acusación o defensa, el conocimiento de la identidad de los testigos o peritos propuestos, cuya declaración o informe sea estimado pertinente, el Juez o Tribunal, en el mismo auto en el que declare la pertinencia de la prueba propuesta:","o":["podrá facilitar el nombre y apellidos de los testigos y peritos, previa audiencia del Ministerio Fiscal.","deberá facilitar todos los datos identificativos de los testigos y peritos, incluido su domicilio.","deberá facilitar el nombre y los apellidos de los testigos y peritos, respetando las restantes garantías reconocidas a los mismos en esta Ley.","deberá facilitar el nombre y los apellidos de los testigos y peritos, sin respetar el resto de garantías, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">deberá facilitar el nombre y los apellidos de los testigos y peritos, respetando las restantes garantías reconocidas a los mismos en esta Ley</mark></span><span class=\"ref-norma\">Art. 4.3 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"deberá facilitar el nombre y los apellidos de los testigos y peritos, respetando las restantes garantías reconocidas a los mismos en esta Ley\"</span>Debe facilitar nombre y apellidos, respetando las restantes garantías de la Ley."},{"i":"21-24","p":"Ley Orgánica 19/1994, de protección a testigos y peritos en causas criminales. En los ____ siguientes a la notificación a las partes de la identidad de los testigos, cualquiera de ellos podrá proponer nueva prueba tendente a acreditar alguna circunstancia que pueda influir en el valor probatorio de su testimonio.","o":["Diez días.","Veinte días.","Cinco días.","Siete días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cinco días</mark></span><span class=\"ref-norma\">Art. 4 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"días siguientes a la notificación a las partes de la identidad de los testigos, cualquiera de ellos podrá proponer nueva prueba tendente a acreditar alguna circunstancia que pueda influir en el valor probatorio de su testimonio\"</span>"},{"i":"21-ia-1152","p":"Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales. Tras facilitarse la identidad de los testigos, en los cinco días siguientes a la notificación a las partes, cualquiera de ellos podrá proponer:","o":["la recusación de los testigos y peritos protegidos.","nueva prueba tendente a acreditar alguna circunstancia que pueda influir en el valor probatorio de su testimonio.","la modificación de las medidas de protección adoptadas por el Juez de Instrucción, salvo que la autoridad judicial disponga otra cosa.","la declaración de los testigos por videoconferencia desde otra sede."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">nueva prueba tendente a acreditar alguna circunstancia que pueda influir en el valor probatorio de su testimonio</mark></span><span class=\"ref-norma\">Art. 4.3 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"cualquiera de ellos podrá proponer nueva prueba tendente a acreditar alguna circunstancia que pueda influir en el valor probatorio de su testimonio\"</span>Cualquiera de ellos puede proponer nueva prueba sobre circunstancias que influyan en el valor probatorio del testimonio."},{"i":"21-ia-1153","p":"Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales. De igual forma, las partes podrán hacer uso del derecho de proponer nueva prueba, a la vista de las pruebas solicitadas por las otras partes y admitidas por el órgano judicial, en el plazo previsto para:","o":["la interposición de recurso de reforma y apelación.","la presentación del escrito de calificación provisional.","la interposición del recurso de súplica y queja.","la proposición de prueba en el juicio oral."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la interposición de recurso de reforma y apelación</mark></span><span class=\"ref-norma\">Art. 4.4 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"en el plazo previsto para la interposición de recurso de reforma y apelación\"</span>El plazo es el previsto para interponer recurso de reforma y apelación."},{"i":"21-ia-1154","p":"Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales. Las declaraciones o informes de los testigos y peritos que hayan sido objeto de protección en aplicación de esta Ley durante la fase de instrucción solamente podrán tener valor de prueba, a efectos de sentencia, si son:","o":["ratificados ante el Juez de Instrucción en la forma prescrita en la Ley de Enjuiciamiento Criminal.","aportados por el Ministerio Fiscal en el acto del juicio oral con garantías de contradicción.","ratificados por escrito, sin que sea preciso acudir al acto del juicio oral.","ratificados en el acto del juicio oral en la forma prescrita en la Ley de Enjuiciamiento Criminal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ratificados en el acto del juicio oral en la forma prescrita en la Ley de Enjuiciamiento Criminal</mark></span><span class=\"ref-norma\">Art. 4.5 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"solamente podrán tener valor de prueba, a efectos de sentencia, si son ratificados en el acto del juicio oral en la forma prescrita en la Ley de Enjuiciamiento Criminal\"</span>Solo valen como prueba si se ratifican en el acto del juicio oral."},{"i":"21-ia-1155","p":"Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales. Si las declaraciones o informes de los testigos y peritos protegidos se consideraran de imposible reproducción, habrán de ser ratificados:","o":["mediante resumen del Letrado de la Administración de Justicia, sin contradicción de las partes.","mediante lectura literal, sin que puedan ser sometidos a contradicción por las partes.","mediante lectura literal a fin de que puedan ser sometidos a contradicción por las partes.","mediante comparecencia del testigo por videoconferencia, con contradicción de las partes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">mediante lectura literal a fin de que puedan ser sometidos a contradicción por las partes</mark></span><span class=\"ref-norma\">Art. 4.5 · Ley Orgánica 19/1994, de 23 de diciembre, de Protección a Testigos y Peritos en Causas Criminales</span><span class=\"ref-concepto\">\"habrán de ser ratificados mediante lectura literal a fin de que puedan ser sometidos a contradicción por las partes\"</span>Si son de imposible reproducción se ratifican por lectura literal para poder someterlos a contradicción."}]},{"a":"Artículo único R6","q":[{"i":"21-154","p":"Ley Orgánica 3/2003, de 21 de mayo, Complementaria de la Ley Reguladora de los Equipos Conjuntos de Investigación Penal en el Ámbito de la Unión Europea, por la que se establece el Régimen de Responsabilidad Penal de los Miembros Destinados en dichos Equipos cuando actúen en España. ¿A qué régimen de responsabilidad penal están sujetos los miembros del equipo de investigación en el ejercicio de sus actividades?:","o":["Régimen de responsabilidad penal internacional.","Régimen de responsabilidad penal propio del equipo de investigación.","Mismo régimen de responsabilidad penal que las autoridades y sus agentes y los funcionarios públicos españoles.","Régimen de responsabilidad penal especial para investigadores extranjeros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Mismo régimen de responsabilidad penal que las autoridades y sus agentes y los funcionarios públicos españoles</mark></span><span class=\"ref-norma\">Art. 4 · Derecho Procesal Penal (II). Normativa complementaria</span><span class=\"ref-concepto\">\"los miembros destinados estarán sujetos al mismo régimen de responsabilidad penal que las autoridades y sus agentes y los funcionarios públicos españoles\"</span>"},{"i":"21-163","p":"Ley Orgánica 3/2003, de 21 de mayo, complementaria de la Ley reguladora de los equipos conjuntos de investigación penal en el ámbito de la Unión Europea, por la que se establece el régimen de responsabilidad penal de los miembros destinados en dichos equipos cuando actúen en España. El régimen de responsabilidad penal de los miembros destinados en los equipos conjuntos de investigación cuando desarrollen su actividad en nuestro país abarca:","o":["Las infracciones penales que pueden cometerse contra los miembros destinados en los equipos conjuntos de investigación.","Los delitos que pudieran cometerse por ellos mismos.","A y B son correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span><span class=\"ref-norma\">Art. 4 · Derecho Procesal Penal (II). Normativa complementaria</span><span class=\"ref-concepto\">\"Dicho régimen abarca tanto las infracciones penales que puedan cometerse contra los miembros destinados en los equipos conjuntos de investigación, como los delitos que pudieran cometerse por ellos mismos\"</span>"},{"i":"21-ia-1101","p":"Ley Orgánica 3/2003, de 21 de mayo, complementaria de la Ley reguladora de los equipos conjuntos de investigación penal. Responsabilidad penal de los miembros destinados en equipos conjuntos de investigación. En el ejercicio de las actividades propias de la investigación desarrolladas por el equipo, los miembros destinados estarán sujetos:","o":["al mismo régimen de responsabilidad penal que las autoridades y sus agentes y los funcionarios públicos españoles.","a un régimen de responsabilidad penal propio del equipo conjunto de investigación, en los términos que se determinen reglamentariamente.","al régimen de responsabilidad penal de su Estado miembro de origen.","a un régimen especial de responsabilidad penal para investigadores extranjeros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al mismo régimen de responsabilidad penal que las autoridades y sus agentes y los funcionarios públicos españoles</mark></span><span class=\"ref-norma\">Art. único.1 · Ley Orgánica 3/2003, de 21 de mayo, complementaria de la Ley reguladora de los equipos conjuntos de investigación penal</span><span class=\"ref-concepto\">\"los miembros destinados estarán sujetos al mismo régimen de responsabilidad penal que las autoridades y sus agentes y los funcionarios públicos españoles\"</span>Rige el mismo régimen que para las autoridades, sus agentes y los funcionarios públicos españoles."},{"i":"21-ia-1102","p":"Ley Orgánica 3/2003, de 21 de mayo, complementaria de la Ley reguladora de los equipos conjuntos de investigación penal. Responsabilidad penal de los miembros destinados en equipos conjuntos de investigación. Igualmente, a los miembros destinados les serán aplicables, en los mismos términos, las disposiciones recogidas al efecto en la legislación penal respecto a las infracciones penales cometidas contra:","o":["los miembros de las Fuerzas y Cuerpos de Seguridad del Estado exclusivamente.","los miembros de los equipos conjuntos de investigación de cualquier Estado miembro.","las autoridades judiciales y fiscales españolas únicamente.","las autoridades y sus agentes y los funcionarios públicos españoles."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las autoridades y sus agentes y los funcionarios públicos españoles</mark></span><span class=\"ref-norma\">Art. único.2 · Ley Orgánica 3/2003, de 21 de mayo, complementaria de la Ley reguladora de los equipos conjuntos de investigación penal</span><span class=\"ref-concepto\">\"les serán aplicables, en los mismos términos, las disposiciones recogidas al efecto en la legislación penal respecto a las infracciones penales cometidas contras las autoridades y sus agentes y los funcionarios públicos españoles\"</span>También se protege a los miembros destinados como a las autoridades, sus agentes y funcionarios públicos españoles."}]},{"a":"Artículo 2 R7","q":[{"i":"21-ia-1112","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. La base de datos policial de identificadores obtenidos a partir del ADN dependerá del __________, a través de la Secretaría de Estado de Seguridad:","o":["Ministerio de Defensa","Ministerio del Interior","Ministerio de Justicia","Ministerio de la Presidencia"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Ministerio del Interior</mark></span><span class=\"ref-norma\">Art. 2 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"dependerá del Ministerio del Interior a través de la Secretaría de Estado de Seguridad\"</span>Depende del Ministerio del Interior a través de la Secretaría de Estado de Seguridad."},{"i":"21-90","p":"Ley Orgánica 10/2007, de 8 de Octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. La base de datos policial de identificadores obtenidos a partir del ADN dependerá del: Señale la correcta.","o":["Ministerio del Interior, a través de la Secretaría de Estado de Seguridad.","Ministerio de Defensa, a través de la Secretaría de Estado de Seguridad.","Ministerio de Exterior, a través de la Secretaría de Estado de Seguridad.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ministerio del Interior, a través de la Secretaría de Estado de Seguridad</mark></span><span class=\"ref-norma\">Art. 4 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores</span><span class=\"ref-concepto\">\"dependerá del Ministerio del Interior a través de la Secretaría de Estado de Seguridad\"</span>"}]},{"a":"Artículo 8 R8","q":[{"i":"21-113","p":"Ley Orgánica 10/2007, de 8 de Octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. Todos los ficheros que integran la base de datos objeto de esta Ley están sometidos.","o":["Al nivel de seguridad medio.","Al nivel de seguridad alto.","Al nivel de seguridad Extremo.","Al nivel de seguridad Severo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al nivel de seguridad alto</mark></span><span class=\"ref-norma\">Art. 8 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores</span><span class=\"ref-concepto\">\"Todos los ficheros que integran la base de datos objeto de esta Ley están sometidos al nivel de seguridad alto\"</span>"}]},{"a":"Artículo 9","q":[{"i":"21-ia-1126","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. La conservación de los identificadores obtenidos a partir del ADN no superará el tiempo señalado en la ley para la cancelación de antecedentes penales, si se hubiese dictado sentencia condenatoria firme, o absolutoria:","o":["por la concurrencia de causas de extinción de la responsabilidad criminal, salvo resolución judicial en contrario.","por la concurrencia de causas eximentes por falta de imputabilidad o culpabilidad, sin posible resolución judicial en contrario.","por cualquier causa, salvo que el Ministerio Fiscal solicite su conservación.","por la concurrencia de causas eximentes por falta de imputabilidad o culpabilidad, salvo resolución judicial en contrario."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por la concurrencia de causas eximentes por falta de imputabilidad o culpabilidad, salvo resolución judicial en contrario</mark></span><span class=\"ref-norma\">Art. 9.1 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"o absolutoria por la concurrencia de causas eximentes por falta de imputabilidad o culpabilidad, salvo resolución judicial en contrario\"</span>Se cancelan por antecedentes penales en condenatoria firme o absolutoria por eximentes de imputabilidad o culpabilidad, salvo resolución judicial en contrario."},{"i":"21-ia-1128","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. En el caso de sospechosos no imputados, la cancelación de los identificadores inscritos se producirá transcurrido el tiempo señalado en la Ley para:","o":["la cancelación de antecedentes penales.","la prescripción del delito.","la prescripción de la pena.","el sobreseimiento de la causa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la prescripción del delito</mark></span><span class=\"ref-norma\">Art. 9.1 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"En el caso de sospechosos no imputados, la cancelación de los identificadores inscritos se producirá transcurrido el tiempo señalado en la Ley para la prescripción del delito\"</span>Para sospechosos no imputados se cancela transcurrido el plazo de prescripción del delito."},{"i":"21-69","p":"Ley Orgánica 10/2007. Base de datos policial sobre identificadores obtenidos a partir del ADN. La conservación de los identificadores obtenidos a partir del ADN en la base de datos no superará:","o":["Tres años desde la inscripción de los identificadores en la base de datos.","Diez años desde la inscripción de los identificadores en la base de datos.","Veinte años desde la inscripción de los identificadores en la base de datos.","El tiempo señalado en la ley para la prescripción del delito."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El tiempo señalado en la ley para la prescripción del delito</mark></span><span class=\"ref-norma\">Art. 9 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores</span><span class=\"ref-concepto\">\"no superará: El tiempo señalado en la ley para la prescripción del delito\"</span>"},{"i":"21-ia-1127","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. En todo caso se procederá a la cancelación de los identificadores cuando se hubiese dictado auto de sobreseimiento libre o sentencia absolutoria por causas distintas de las mencionadas en el epígrafe anterior, una vez que:","o":["transcurran seis meses desde dichas resoluciones.","así lo solicite el interesado ante el encargado de la base de datos.","sean firmes dichas resoluciones.","lo acuerde el Juez mediante auto motivado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">sean firmes dichas resoluciones</mark></span><span class=\"ref-norma\">Art. 9.1 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"una vez que sean firmes dichas resoluciones\"</span>La cancelación procede una vez firmes dichas resoluciones."},{"i":"21-ia-1129","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. Si en la base de datos existiesen diversas inscripciones de una misma persona, correspondientes a diversos delitos, los datos y patrones identificativos inscritos se mantendrán hasta que:","o":["finalice el plazo de cancelación más amplio.","finalice el plazo de cancelación más breve.","transcurra el plazo de prescripción del delito más grave.","se dicte sentencia firme en el último procedimiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">finalice el plazo de cancelación más amplio</mark></span><span class=\"ref-norma\">Art. 9.1 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"se mantendrán hasta que finalice el plazo de cancelación más amplio\"</span>Se mantienen hasta que finalice el plazo de cancelación más amplio."},{"i":"21-ia-1131","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. Tratándose de patrones obtenidos en procedimientos de identificación de restos cadavéricos o de averiguación de personas desaparecidas, los datos inscritos no se cancelarán mientras sean necesarios para:","o":["la ejecución de la sentencia que pudiera dictarse.","la identificación de otros restos cadavéricos.","la finalización de los correspondientes procedimientos.","la comunicación a las autoridades de terceros países, sin perjuicio de lo previsto en la normativa vigente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la finalización de los correspondientes procedimientos</mark></span><span class=\"ref-norma\">Art. 9.2 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"los datos inscritos no se cancelarán mientras sean necesarios para la finalización de los correspondientes procedimientos\"</span>No se cancelan mientras sean necesarios para finalizar los procedimientos."},{"i":"21-ia-1130","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. Los datos pertenecientes a personas fallecidas se cancelarán:","o":["transcurridos diez años desde el fallecimiento.","una vez se dicte la correspondiente resolución judicial.","en el plazo de seis meses desde que se acredite el fallecimiento, previo informe de la unidad policial competente.","una vez el encargado de la base de datos tenga conocimiento del fallecimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una vez el encargado de la base de datos tenga conocimiento del fallecimiento</mark></span><span class=\"ref-norma\">Art. 9.2 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"Los datos pertenecientes a personas fallecidas se cancelarán una vez el encargado de la base de datos tenga conocimiento del fallecimiento\"</span>Se cancelan cuando el encargado conoce el fallecimiento."},{"i":"21-ia-1132","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. Una vez identificada la persona cuyos identificadores permanecían inscritos de forma anónima, se aplicará lo dispuesto en este artículo a efectos de su __________:","o":["conservación","cancelación","cesión","rectificación"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cancelación</mark></span><span class=\"ref-norma\">Art. 9.4 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"Una vez identificados, se aplicará lo dispuesto en este artículo a efectos de su cancelación\"</span>Una vez identificados, se aplica el régimen de cancelación."},{"i":"21-133","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. Los identificadores obtenidos a partir del ADN respecto de los que se desconozca la identidad de la persona a la que corresponden, permanecerán inscritos:","o":["Los tres años.","Los dos años.","Los veinte años.","En tanto se mantenga dicho anonimato."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En tanto se mantenga dicho anonimato</mark></span><span class=\"ref-norma\">Art. 9 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores</span><span class=\"ref-concepto\">\"permanecerán inscritos en tanto se mantenga dicho anonimato\"</span>"},{"i":"21-138","p":"Ley Orgánica 10/2007, de 8 de octubre, Reguladora de la Base de Datos Policial sobre Identificadores Obtenidos a partir del ADN. ¿Qué acción se compromete a realizar el Ministerio del Interior según la disposición adicional primera?:","o":["Integrar los ficheros y bases de datos de ADN existentes en la nueva base de datos policial.","Desarrollar un nuevo sistema de identificación basado en ADN.","Eliminar las bases de datos de ADN anteriores a la ley.","Crear una base de datos de ADN independiente para cada cuerpo de seguridad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Integrar los ficheros y bases de datos de ADN existentes en la nueva base de datos policial</mark></span><span class=\"ref-norma\">Art. 9 · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores</span><span class=\"ref-concepto\">\"El Ministerio del Interior adoptará las medidas oportunas para que los diferentes ficheros y bases de datos de identificadores obtenidos a partir del ADN\"</span>"},{"i":"21-ia-1137","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. Mediante la suscripción del oportuno convenio, será posible la integración en la nueva base de datos de los datos procedentes de otros ficheros, registros o bases de datos de identificadores obtenidos a partir del ADN, distintos a los de las Fuerzas y Cuerpos de Seguridad del Estado, siempre que los mismos hubieran sido creados con las únicas finalidades de:","o":["investigación y averiguación de los delitos enumerados, identificación de cadáveres o averiguación de personas desaparecidas.","investigación y averiguación de cualquier delito, identificación de cadáveres o averiguación de personas desaparecidas, salvo que la autoridad judicial disponga otra cosa.","investigación y averiguación de los delitos enumerados y determinación de relaciones de parentesco.","investigación de los delitos enumerados y prevención de delitos por el Centro Nacional de Inteligencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">investigación y averiguación de los delitos enumerados, identificación de cadáveres o averiguación de personas desaparecidas</mark></span><span class=\"ref-norma\">Disposición adicional primera · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"siempre que los mismos hubieran sido creados con las únicas finalidades de investigación y averiguación de los delitos\"</span>Solo pueden integrarse si se crearon con las únicas finalidades de investigación y averiguación de los delitos enumerados, identificación de cadáveres o averiguación de desaparecidos."},{"i":"21-ia-1133","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. La LO 10/2007 se inscribe en el marco de lo dispuesto en la Ley Orgánica de Protección de Datos de Carácter Personal, la cual, por su propia naturaleza, resulta de:","o":["aplicación directa.","aplicación supletoria.","aplicación subsidiaria.","aplicación preferente en caso de conflicto."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">aplicación directa</mark></span><span class=\"ref-norma\">Disposición adicional segunda · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"la cual, por su propia naturaleza, resulta de aplicación directa\"</span>La Ley de Protección de Datos es de aplicación directa."},{"i":"21-ia-1134","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. Para la investigación de los delitos enumerados, la policía judicial procederá a la toma de muestras y fluidos del sospechoso, detenido o imputado, así como:","o":["de los familiares de la víctima.","de los testigos del delito.","de los objetos de la víctima.","del lugar del delito."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">del lugar del delito</mark></span><span class=\"ref-norma\">Disposición adicional tercera · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"la policía judicial procederá a la toma de muestras y fluidos del sospechoso, detenido o imputado, así como del lugar del delito\"</span>Se toman muestras del sospechoso, detenido o imputado y del lugar del delito."},{"i":"21-ia-1135","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. La toma de muestras que requieran inspecciones, reconocimientos o intervenciones corporales, sin consentimiento del afectado, requerirá en todo caso:","o":["autorización del Ministerio Fiscal, de acuerdo con lo establecido en la Ley de Enjuiciamiento Criminal.","autorización judicial mediante providencia, de acuerdo con lo establecido en la ley orgánica reguladora, en los términos que se determinen reglamentariamente.","autorización judicial mediante auto motivado, de acuerdo con lo establecido en la Ley de Enjuiciamiento Criminal.","informe del médico forense y autorización de la Policía Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">autorización judicial mediante auto motivado, de acuerdo con lo establecido en la Ley de Enjuiciamiento Criminal</mark></span><span class=\"ref-norma\">Disposición adicional tercera · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"requerirá en todo caso autorización judicial mediante auto motivado, de acuerdo con lo establecido en la Ley de Enjuiciamiento Criminal\"</span>Sin consentimiento exige siempre autorización judicial mediante auto motivado."},{"i":"21-ia-1136","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. Los laboratorios del Instituto Nacional de Toxicología y Ciencias Forenses podrán realizar los correspondientes análisis del ADN para identificación genética, de acuerdo con las funciones que le atribuye:","o":["la Ley de Enjuiciamiento Criminal.","la Ley Orgánica del Poder Judicial.","la Ley Orgánica de Protección de Datos de Carácter Personal.","la Ley General de Sanidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Ley Orgánica del Poder Judicial</mark></span><span class=\"ref-norma\">Disposición adicional cuarta · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"de acuerdo con las funciones que le atribuye la Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial\"</span>Sus funciones las atribuye la Ley Orgánica del Poder Judicial."},{"i":"21-ia-1138","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. Los laboratorios de las Fuerzas y Cuerpos de Seguridad del Estado que a la entrada en vigor de la Ley no estuviesen debidamente acreditados dispondrán del plazo de __________ para hacerlo, a contar desde dicha fecha:","o":["seis meses","dos años","tres meses","un año"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un año</mark></span><span class=\"ref-norma\">Disposición transitoria única · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"dispondrán del plazo de un año para hacerlo, a contar desde dicha fecha\"</span>Disponen de un año desde la entrada en vigor."},{"i":"21-ia-1139","p":"Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN. Quedan derogadas cuantas normas de igual o inferior rango:","o":["regulen los ficheros de ADN de las Fuerzas y Cuerpos de Seguridad del Estado.","contradigan o se opongan a lo dispuesto en la Ley de Protección de Datos.","contradigan o se opongan a lo dispuesto en la presente Ley.","se hubieran dictado con anterioridad a la entrada en vigor de la presente Ley."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">contradigan o se opongan a lo dispuesto en la presente Ley</mark></span><span class=\"ref-norma\">Disposición derogatoria única · Ley Orgánica 10/2007, de 8 de octubre, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN</span><span class=\"ref-concepto\">\"Quedan derogadas cuantas normas de igual o inferior rango contradigan o se opongan a lo dispuesto en la presente Ley\"</span>Se derogan las normas de igual o inferior rango que la contradigan."}]},{"a":"Artículo 4 ✱ R15","q":[{"i":"21-ia-1308","p":"Ley 11/2003, de 21 de mayo, reguladora de los equipos conjuntos de investigación penal en el ámbito de la Unión Europea. Corresponderá a la autoridad competente española valorar y adoptar, en su caso, los acuerdos de constitución de equipos conjuntos de investigación que:","o":["vayan a actuar fuera de España.","vayan a actuar en España.","soliciten Eurojust o Europol.","afecten a delitos de terrorismo exclusivamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">vayan a actuar en España</mark></span><span class=\"ref-norma\">Art.  4 · Ley 11/2003, de 21 de mayo, reguladora de los equipos conjuntos de investigación penal en el ámbito de la Unión Europea</span><span class=\"ref-concepto\">\"Corresponderá a la autoridad competente española valorar y adoptar, en su caso, los acuerdos de constitución de equipos conjuntos de investigación que vayan a actuar en España\"</span>Valora y adopta los acuerdos de los equipos que vayan a actuar en España."},{"i":"21-76","p":"Ley 11/2003 reguladora de los equipos conjuntos de investigación penal en ámbito de la Unión Europea. La autoridad competente española otorgará preferencia en todos los casos a las investigaciones relacionadas con:","o":["Delitos de lesa humanidad.","Delitos de terrorismo.","Delitos de gravedad.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Delitos de terrorismo</mark></span><span class=\"ref-norma\">Art. 4 · Ley 11/2003, de 21 de mayo, reguladora de los equipos conjuntos de investigación penal en el ámbito de la</span><span class=\"ref-concepto\">\"La autoridad competente española otorgará preferencia en todos los casos a las investigaciones relacionadas con delitos de terrorismo\"</span>"},{"i":"21-203","p":"Ley 11/2003, de 21 de mayo, reguladora de los equipos conjuntos de investigación penal en el ámbito de la Unión Europea. Adopción del acuerdo de constitución. ¿Qué prioridad establece esta ley para las investigaciones llevadas a cabo por equipos conjuntos de investigación en España?","o":["Dar preferencia a las investigaciones de delitos fiscales.","Priorizar las investigaciones relacionadas con delitos de terrorismo.","Centrarse exclusivamente en delitos de narcotráfico.","Ignorar las investigaciones que no involucren a miembros judiciales o fiscales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Priorizar las investigaciones relacionadas con delitos de terrorismo</mark></span><span class=\"ref-norma\">Art. 4 · Ley 11/2003, de 21 de mayo, reguladora de los equipos conjuntos de investigación penal en el ámbito de la</span><span class=\"ref-concepto\">\"La autoridad competente española otorgará preferencia en todos los casos a las investigaciones relacionadas con delitos de terrorismo\"</span>"}]},{"a":"Artículo 8 ✱","q":[{"i":"21-ia-1319","p":"Ley 11/2003, de 21 de mayo, reguladora de los equipos conjuntos de investigación penal en el ámbito de la Unión Europea. La información que puedan obtener los miembros del equipo conjunto de investigación podrá utilizarse para descubrir, investigar y enjuiciar otras infracciones penales, previa autorización del Estado en el que hayan obtenido la información. Dicha autorización únicamente podrá denegarse cuando:","o":["la utilización de la información afecte a la seguridad pública de aquel Estado.","la infracción investigada no esté tipificada en la legislación de aquel Estado.","la utilización de la información ponga en peligro otras investigaciones penales en aquel Estado.","la utilización de la información no haya sido convenida por todos los Estados del equipo, salvo que la autoridad judicial disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la utilización de la información ponga en peligro otras investigaciones penales en aquel Estado</mark></span><span class=\"ref-norma\">Art.  8 · Ley 11/2003, de 21 de mayo, reguladora de los equipos conjuntos de investigación penal en el ámbito de la Unión Europea</span><span class=\"ref-concepto\">\"Dicha autorización únicamente podrá denegarse cuando la utilización de la información ponga en peligro otras investigaciones penales en aquel Estado\"</span>Solo se deniega si pone en peligro otras investigaciones penales en aquel Estado."},{"i":"21-ia-1320","p":"Ley 11/2003, de 21 de mayo, reguladora de los equipos conjuntos de investigación penal en el ámbito de la Unión Europea. La información obtenida por los miembros del equipo podrá utilizarse para evitar una amenaza inmediata y grave para la seguridad pública, sin perjuicio de lo dispuesto sobre:","o":["la autorización del Ministerio de Justicia para la cesión a terceros Estados, previo informe de la unidad policial competente.","la autorización del Estado en el que hayan obtenido la información para otras infracciones penales.","el consentimiento de todos los Estados que crearon el equipo.","la información a las comunidades autónomas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la autorización del Estado en el que hayan obtenido la información para otras infracciones penales</mark></span><span class=\"ref-norma\">Art.  8 · Ley 11/2003, de 21 de mayo, reguladora de los equipos conjuntos de investigación penal en el ámbito de la Unión Europea</span><span class=\"ref-concepto\">\"c) Para evitar una amenaza inmediata y grave para la seguridad pública, sin perjuicio de lo dispuesto en el párrafo b) de este artículo\"</span>Se entiende sin perjuicio de la autorización prevista para otras infracciones penales."},{"i":"21-ia-1321","p":"Ley 11/2003, de 21 de mayo, reguladora de los equipos conjuntos de investigación penal en el ámbito de la Unión Europea. La información obtenida por los miembros del equipo podrá utilizarse para otros fines, siempre y cuando:","o":["así lo hayan convenido los Estados que crearon el equipo.","lo autorice el Estado en el que se obtuvo la información, sin perjuicio de lo previsto en la normativa vigente.","lo autorice la autoridad competente española.","lo apruebe Eurojust a propuesta del jefe del equipo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">así lo hayan convenido los Estados que crearon el equipo</mark></span><span class=\"ref-norma\">Art.  8 · Ley 11/2003, de 21 de mayo, reguladora de los equipos conjuntos de investigación penal en el ámbito de la Unión Europea</span><span class=\"ref-concepto\">\"d) Para otros fines, siempre y cuando así lo hayan convenido los Estados que crearon el equipo\"</span>Para otros fines hace falta convenio de los Estados que crearon el equipo."}]},{"a":"Artículo 5","q":[{"i":"21-126","p":"Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. Periodo de conservación de datos. La obligación de conservación de datos impuesta cesa _____ computados desde la fecha en que se haya producido la comunicación.","o":["A los dos años.","A los doce meses.","A los seis meses.","A los tres meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A los doce meses</mark></span><span class=\"ref-norma\">Art. 5 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las</span><span class=\"ref-concepto\">\"La obligación de conservación de datos impuesta cesa a los doce meses computados desde la fecha en que se haya producido la comunicación\"</span>"},{"i":"21-202","p":"Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. Período de conservación de los datos. La obligación de conservación de datos impuesta cesa a los _____ computados desde la fecha en que se haya producido la comunicación.","o":["Seis meses.","Dieciocho meses.","Ocho años.","Doce meses."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Doce meses</mark></span><span class=\"ref-norma\">Art. 5 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las</span><span class=\"ref-concepto\">\"La obligación de conservación de datos impuesta cesa a los doce meses computados desde la fecha en que se haya producido la comunicación\"</span>"},{"i":"21-ia-1415","p":"Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. La obligación de conservación de datos impuesta cesa a los __________ computados desde la fecha en que se haya producido la comunicación:","o":["seis meses","dieciocho meses","doce meses","dos años"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">doce meses</mark></span><span class=\"ref-norma\">Art.  5.1 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones</span><span class=\"ref-concepto\">\"La obligación de conservación de datos impuesta cesa a los doce meses computados desde la fecha en que se haya producido la comunicación\"</span>El plazo general es de doce meses."},{"i":"21-116","p":"Ley 25/2007, de 18 de Octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. Reglamentariamente, previa consulta a los operadores, se podrá ampliar o reducir el plazo de conservación para determinados datos o una categoría de datos hasta un máximo de ______ o un mínimo de ______.","o":["Tres años / seis meses.","Dos años / seis meses.","Cinco años / seis meses.","Cuatro años / cuatro meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos años / seis meses</mark></span><span class=\"ref-norma\">Art. 5 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las</span><span class=\"ref-concepto\">\"hasta un máximo de dos años o un mínimo de seis meses\"</span>"},{"i":"21-245","p":"Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. La obligación de conservación de datos impuesta cesa:","o":["A los doce meses computados desde la fecha en que se haya producido la comunicación.","A los seis meses computados desde la fecha en que se haya producido la comunicación.","A los quince meses computados desde la fecha en que se haya producido la comunicación.","A los veinticuatro meses computados desde la fecha en que se haya producido la comunicación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A los doce meses computados desde la fecha en que se haya producido la comunicación</mark></span><span class=\"ref-norma\">Art. 5 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las</span><span class=\"ref-concepto\">\"La obligación de conservación de datos impuesta cesa a los doce meses computados desde la fecha en que se haya producido la comunicación\"</span>"},{"i":"21-ia-1416","p":"Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. Reglamentariamente, previa consulta a los operadores, se podrá ampliar o reducir el plazo de conservación para determinados datos o una categoría de datos tomando en consideración:","o":["la naturaleza del dato y la gravedad del delito investigado, previo informe de la Agencia de Protección de Datos, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","el coste del almacenamiento y conservación de los datos, así como el interés de los mismos para los fines de investigación, detección y enjuiciamiento de un delito grave.","el coste del almacenamiento y el informe del Ministerio del Interior sobre su interés para la investigación.","el interés de los datos para la investigación de delitos graves, con independencia de su coste."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el coste del almacenamiento y conservación de los datos, así como el interés de los mismos para los fines de investigación, detección y enjuiciamiento de un delito grave</mark></span><span class=\"ref-norma\">Art.  5.1 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones</span><span class=\"ref-concepto\">\"tomando en consideración el coste del almacenamiento y conservación de los datos, así como el interés de los mismos para los fines de investigación, detección y enjuiciamiento de un delito grave\"</span>Se atiende al coste y al interés para investigar delitos graves."}]},{"a":"Artículo 7 R17","q":[{"i":"21-ia-1420","p":"Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. Los operadores estarán obligados a ceder al agente facultado los datos conservados concernientes a comunicaciones que identifiquen a personas, sin perjuicio de:","o":["la autorización de la Agencia de Protección de Datos, previo informe de la unidad policial competente.","la resolución judicial prevista en el apartado siguiente.","la comunicación al abonado afectado.","el informe del Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la resolución judicial prevista en el apartado siguiente</mark></span><span class=\"ref-norma\">Art.  7.1 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones</span><span class=\"ref-concepto\">\"sin perjuicio de la resolución judicial prevista en el apartado siguiente\"</span>Se ceden sin perjuicio de la resolución judicial."},{"i":"21-25","p":"Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. Conservación de datos relativos a las comunicaciones electrónicas. La resolución judicial determinará, conforme a lo previsto en la Ley de Enjuiciamiento Criminal y de acuerdo con los principios de ______ los datos conservados que han de ser cedidos a los agentes facultados.","o":["Idoneidad y proporcionalidad.","Oportunidad y proporcionalidad.","Necesidad y proporcionalidad.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Necesidad y proporcionalidad</mark></span><span class=\"ref-norma\">Art. 7 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las</span><span class=\"ref-concepto\">\"de acuerdo con los principios de necesidad y proporcionalidad, los datos conservados que han de ser cedidos a los agentes facultados\"</span>"},{"i":"21-ia-1421","p":"Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. La resolución judicial determinará, conforme a lo previsto en la Ley de Enjuiciamiento Criminal y de acuerdo con los principios de necesidad y proporcionalidad, los datos conservados que han de ser:","o":["cedidos a los agentes facultados.","conservados por los operadores.","cancelados una vez finalizada la investigación.","comunicados al abonado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cedidos a los agentes facultados</mark></span><span class=\"ref-norma\">Art.  7.2 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones</span><span class=\"ref-concepto\">\"los datos conservados que han de ser cedidos a los agentes facultados\"</span>Determina los datos que han de cederse a los agentes facultados."},{"i":"21-ia-1423","p":"Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. El plazo de ejecución de la orden de cesión se fijará por la resolución judicial atendiendo a la urgencia de la cesión y a los efectos de la investigación de que se trate, así como a:","o":["la gravedad del delito y la complejidad de la investigación.","la capacidad técnica del operador y su coste.","la naturaleza y complejidad técnica de la operación.","la solicitud del agente facultado y el informe del Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la naturaleza y complejidad técnica de la operación</mark></span><span class=\"ref-norma\">Art.  7.3 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones</span><span class=\"ref-concepto\">\"así como a la naturaleza y complejidad técnica de la operación\"</span>También atiende a la naturaleza y complejidad técnica de la operación."},{"i":"21-ia-1422","p":"Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. El plazo de ejecución de la orden de cesión será el fijado por la resolución judicial. Si no se establece otro plazo distinto, la cesión deberá efectuarse dentro del plazo de:","o":["7 días hábiles contados a partir de las 8:00 horas del día siguiente a aquél en que el sujeto obligado reciba la orden, sin perjuicio de lo previsto en la normativa vigente.","10 días naturales contados a partir de las 9:00 horas del día en que el sujeto obligado reciba la orden.","72 horas contadas a partir de que el sujeto obligado reciba la orden.","7 días naturales contados a partir de las 8:00 horas del día natural siguiente a aquél en que el sujeto obligado reciba la orden."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">7 días naturales contados a partir de las 8:00 horas del día natural siguiente a aquél en que el sujeto obligado reciba la orden</mark></span><span class=\"ref-norma\">Art.  7.3 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones</span><span class=\"ref-concepto\">\"la cesión deberá efectuarse dentro del plazo de 7 días naturales contados a partir de las 8:00 horas del día natural siguiente a aquél en que el sujeto obligado reciba la orden\"</span>Son 7 días naturales desde las 8:00 del día natural siguiente."}]},{"a":"Artículo 9 ✱","q":[{"i":"21-ia-1426","p":"Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones. El responsable del tratamiento de los datos no comunicará la cesión de datos efectuada de conformidad con la Ley y denegará el ejercicio del derecho de:","o":["acceso en los términos y condiciones previstos en la Ley de Enjuiciamiento Criminal, salvo que la autoridad judicial disponga otra cosa.","rectificación en los términos previstos en la Ley General de Telecomunicaciones.","oposición en los términos previstos en la Ley Orgánica de Protección de Datos.","cancelación en los términos y condiciones previstos en la Ley Orgánica de Protección de Datos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cancelación en los términos y condiciones previstos en la Ley Orgánica de Protección de Datos</mark></span><span class=\"ref-norma\">Art.  9 · Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones</span><span class=\"ref-concepto\">\"El responsable del tratamiento de los datos denegará el ejercicio del derecho de cancelación en los términos y condiciones previstos en la Ley Orgánica 15/1999, de 13 de diciembre\"</span>Se deniega el derecho de cancelación en los términos de la LOPD."}]},{"a":"Artículo 2","q":[{"i":"21-193","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. ¿Qué se considera un instrumento de reconocimiento mutuo según la ley?","o":["Cualquier resolución judicial emitida en España.","Una orden europea o resolución emitida por un Estado no miembro de la Unión Europea.","Una orden europea o resolución emitida por la autoridad competente de un Estado miembro de la Unión Europea.","Un tratado internacional firmado por España."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Una orden europea o resolución emitida por la autoridad competente de un Estado miembro de la Unión Europea</mark></span><span class=\"ref-norma\">Art. 2 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"Se entiende por instrumento de reconocimiento mutuo aquella orden europea o resolución emitida por la autoridad competente de un Estado miembro de la Unión Europea que se transmite a otro Estado miembro para su reconocimiento y ejecución en el mismo\"</span>"},{"i":"21-ia-1516","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. Los instrumentos de reconocimiento mutuo regulados en la Ley son los siguientes. Señale la INCORRECTA:","o":["La resolución por la que se impone una pena o medida privativa de libertad.","La orden europea de busca y captura.","La resolución sobre medidas de vigilancia de la libertad provisional.","La resolución por la que se imponen sanciones pecuniarias."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La orden europea de busca y captura</mark></span><span class=\"ref-norma\">Art.  2 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"a) La orden europea de detención y entrega. b) La resolución por la que se impone una pena o medida privativa de libertad\"</span>El instrumento es la orden europea de detención y entrega, no de busca y captura."},{"i":"21-ia-2906","p":"Convenio de Viena de 18 de abril de 1961, sobre Relaciones Diplomáticas. El establecimiento de relaciones diplomáticas entre Estados y el envío de misiones diplomáticas permanentes se efectúa:","o":["por decisión del Estado acreditante.","por acuerdo de las Naciones Unidas.","por reciprocidad de trato.","por consentimiento mutuo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por consentimiento mutuo</mark></span><span class=\"ref-norma\">Art.  2 · Convenio de Viena de 18 de abril de 1961, sobre Relaciones Diplomáticas</span><span class=\"ref-concepto\">\"El establecimiento de relacIones diplomáticas entre Estados y .el envio de misiones diplomáticas permanentes se efectúa por consentimiento mutuo\"</span>Se efectúa por consentimiento mutuo."},{"i":"21-ia-3003","p":"Convenio de Viena de 24 de abril de 1963, sobre Relaciones Consulares. El establecimiento de relaciones consulares entre Estados se efectuará:","o":["por notificación del Estado que envía.","por decisión de las Naciones Unidas.","por consentimiento mutuo.","por reciprocidad de trato."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por consentimiento mutuo</mark></span><span class=\"ref-norma\">Art.  2 · Convenio de Viena de 24 de abril de 1963, sobre Relaciones Consulares</span><span class=\"ref-concepto\">\"El establecimiento de relaciones consulares entre Estado:; .'if'- efectuará por consentimiento lhutuO\"</span>Se efectúa por consentimiento mutuo."},{"i":"21-107","p":"Ley 23/2014, de 20 de Noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. Régimen general del reconocimiento mutuo de resoluciones penales en la Unión Europea. Instrumentos de reconocimiento mutuo. Los instrumentos de reconocimiento mutuo regulados en esta Ley son los siguientes, entre otros (señale la correcta):","o":["La orden europea de detención y entrega.","La resolución por la que se impone una pena o medida privativa de libertad.","La resolución de libertad vigilada.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 2 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"h) La resolución por la que se imponen sanciones pecuniarias. i) La orden europea de investigación\"</span>"},{"i":"21-ia-1517","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. Entre los instrumentos de reconocimiento mutuo regulados en la Ley, el último de la lista es:","o":["la orden europea de investigación.","la resolución por la que se imponen sanciones pecuniarias.","la orden europea de protección.","la resolución de decomiso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la orden europea de investigación</mark></span><span class=\"ref-norma\">Art.  2 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"h) La resolución por la que se imponen sanciones pecuniarias. i) La orden europea de investigación\"</span>La lista termina con la orden europea de investigación."}]},{"a":"Artículo 5","q":[{"i":"21-80","p":"Ley 23/2014, de 20 de noviembre, de Reconocimiento mutuo de resoluciones penales de la UE. Se conoce por el Estado miembro de la Unión Europea en el que la autoridad competente ha dictado una orden o resolución al objeto de que sea reconocida y ejecutada en otro Estado miembro:","o":["Estado de ejecución.","Estado de solicitud.","Estado de emisión.","Ninguna opción es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Estado de emisión</mark></span><span class=\"ref-norma\">Art. 5 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"a) Estado de emisión: el Estado miembro de la Unión Europea en el que la autoridad competente ha dictado una orden o resolución de las reguladas en esta Ley al objeto de que sea reconocida y ejecutada en otro Estado miembro\"</span>"},{"i":"21-ia-1520","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. Se entiende por «Estado de ejecución»:","o":["el Estado miembro de la Unión Europea en el que la autoridad competente ha dictado una orden o resolución al objeto de que sea reconocida y ejecutada en otro Estado, previo informe de la unidad policial competente.","el Estado miembro de la Unión Europea al que se ha transmitido una orden o resolución dictada por la autoridad judicial competente de otro Estado miembro, para su reconocimiento y ejecución.","el Estado miembro en cuyo territorio reside habitualmente la persona condenada.","el Estado miembro que ejecuta materialmente la medida acordada por el Estado de emisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Estado miembro de la Unión Europea al que se ha transmitido una orden o resolución dictada por la autoridad judicial competente de otro Estado miembro, para su reconocimiento y ejecución</mark></span><span class=\"ref-norma\">Art.  5 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"b) Estado de ejecución: el Estado miembro de la Unión Europea al que se ha transmitido una orden o resolución dictada por la autoridad judicial competente de otro Estado miembro, para su reconocimiento y ejecución\"</span>Es el Estado al que se transmite la orden o resolución."}]},{"a":"Artículo 6 ✱ R18 R19","q":[{"i":"21-176","p":"Ley 23/2014, de 20 de noviembre, de Reconocimiento Mutuo de Resoluciones Penales en la Unión Europea. ¿Quién debe reflejar la transmisión o ejecución de los instrumentos de reconocimiento mutuo en los boletines estadísticos trimestrales?","o":["El Ministerio del Interior.","La Fiscalía General del Estado.","Los Jueces o Tribunales.","La autoridad judicial del Estado de emisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Jueces o Tribunales</mark></span><span class=\"ref-norma\">Art. 6 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"Los Jueces o Tribunales que transmitan o ejecuten los instrumentos de reconocimiento mutuo previstos en esta Ley lo reflejarán en los boletines estadísticos trimestrales\"</span>"},{"i":"21-ia-1521","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. Los Jueces o Tribunales que transmitan o ejecuten los instrumentos de reconocimiento mutuo lo reflejarán en los boletines estadísticos __________ y lo remitirán al Ministerio de Justicia:","o":["trimestrales","semestrales, sin perjuicio de lo previsto en la normativa vigente.","mensuales","anuales"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">trimestrales</mark></span><span class=\"ref-norma\">Art.  6 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"lo reflejarán en los boletines estadísticos trimestrales y lo remitirán al Ministerio de Justicia\"</span>Los boletines judiciales son trimestrales; la Fiscalía remite semestralmente."},{"i":"21-16","p":"Ley 23/2014, de reconocimiento mutuo de resoluciones penales en la Unión Europea. La Fiscalía General del Estado remitirá ____ al Ministerio de Justicia un listado de los instrumentos de reconocimiento mutuo emitidos o ejecutados por representantes del Ministerio Público.","o":["Mensualmente","Trimestralmente","Semestralmente","Anualmente"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Semestralmente</mark></span><span class=\"ref-norma\">Art. 6 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"La Fiscalía General del Estado remitirá semestralmente al Ministerio de Justicia un listado de los instrumentos de reconocimiento mutuo emitidos o ejecutados por representantes del Ministerio Público\"</span>Los boletines estadísticos de los Jueces son trimestrales; el listado de la Fiscalía es semestral."},{"i":"21-21","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. Régimen general del reconocimiento mutuo de resoluciones penales en la Unión Europea. ¿Qué organismo será la Autoridad Central a la que corresponde la función de auxilio a las autoridades judiciales?","o":["El Ministerio de Justicia.","El Fiscal General del Estado.","La oficina judicial.","La Audiencia Nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministerio de Justicia</mark></span><span class=\"ref-norma\">Art. 6 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"El Ministerio de Justicia será la Autoridad Central a la que corresponde la función de auxilio a las autoridades judiciales\"</span>"}]},{"a":"Artículo 35 ✱ R21","q":[{"i":"21-1","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la unión europea. Son autoridades judiciales competentes para ____ una orden europea de detención y entrega el Juez o Tribunal que conozca de la causa en la que proceda tal tipo de órdenes","o":["Ejecutar","Emitir","Elaborar","Conducir"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Emitir</mark></span><span class=\"ref-norma\">Art. 35 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"Son autoridades judiciales competentes para emitir una orden europea de detención y entrega el Juez o Tribunal que conozca de la causa en la que proceda tal tipo de órdenes\"</span>El Juez o Tribunal que conoce de la causa emite la orden; la autoridad competente para ejecutarla es el Juez Central de Instrucción."},{"i":"21-ia-1614","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. La autoridad judicial competente para ejecutar una orden europea de detención será el Juez Central de Instrucción de la Audiencia Nacional. Cuando la orden se refiera a un menor la competencia corresponderá:","o":["al Juez de Menores del lugar de residencia.","al Juez Central de lo Penal.","al Juez de Instrucción del lugar de detención.","al Juez Central de Menores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al Juez Central de Menores</mark></span><span class=\"ref-norma\">Art.  35 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"Cuando la orden se refiera a un menor la competencia corresponderá al Juez Central de Menores\"</span>Para menores es competente el Juez Central de Menores."},{"i":"21-ia-3539","p":"Instrucción 1/2024, de la Secretaría de Estado de Seguridad, Procedimiento Integral de la Detención Policial. La autoridad judicial competente para ejecutar una orden europea de detención será:","o":["el Juez de Instrucción del lugar de la detención, sin perjuicio de lo previsto en la normativa vigente.","el Juez de Guardia.","el Juez Central de Instrucción de la Audiencia Nacional.","la Audiencia Provincial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Juez Central de Instrucción de la Audiencia Nacional</mark></span><span class=\"ref-norma\">Anexo, punto 10.8 · Instrucción 1/2024, de la Secretaría de Estado de Seguridad, Procedimiento Integral de la Detención Policial</span><span class=\"ref-concepto\">\"será el Juez Central de Instrucción de la Audiencia Nacional\"</span>El Juez Central de Instrucción."},{"i":"21-ia-3540","p":"Instrucción 1/2024, de la Secretaría de Estado de Seguridad, Procedimiento Integral de la Detención Policial. Cuando la orden europea de detención se refiera a un menor, la competencia para ejecutarla corresponderá:","o":["al Juez Central de Instrucción.","al Juez Central de Menores.","al Juez de Menores provincial.","a la Audiencia Provincial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al Juez Central de Menores</mark></span><span class=\"ref-norma\">Anexo, punto 10.8 · Instrucción 1/2024, de la Secretaría de Estado de Seguridad, Procedimiento Integral de la Detención Policial</span><span class=\"ref-concepto\">\"la competencia corresponderá al Juez Central de Menores\"</span>Al Juez Central de Menores."}]},{"a":"Artículo 37 ✱","q":[{"i":"21-20","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. La autoridad judicial española, para el cumplimiento de pena por el reclamado:","o":["Podrá dictar una orden europea de detención y entrega únicamente si el reclamado ya se encuentra en otro Estado miembro.","Podrá dictar una orden europea de detención y entrega.","Podrá dictar como máximo dos órdenes europeos de detención y entrega.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Podrá dictar una orden europea de detención y entrega</mark></span><span class=\"ref-norma\">Art. 37 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"La autoridad judicial española podrá dictar una orden europea de detención y entrega en los siguientes supuestos\"</span>"},{"i":"21-ia-1617","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. La autoridad judicial española podrá dictar una orden europea de detención y entrega con el fin de proceder al ejercicio de acciones penales, por aquellos hechos para los que la ley penal española señale una pena o medida de seguridad privativa de libertad cuya duración máxima sea, al menos, de:","o":["doce meses.","seis meses, previo informe de la unidad policial competente.","dos años.","tres años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">doce meses</mark></span><span class=\"ref-norma\">Art.  37 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"cuya duración máxima sea, al menos, de doce meses\"</span>Para acciones penales: pena de duración máxima de al menos doce meses."},{"i":"21-ia-1618","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. La autoridad judicial española podrá dictar una orden europea de detención y entrega con el fin de proceder al cumplimiento de una condena a una pena o una medida de seguridad no inferior a:","o":["seis meses de privación de libertad, sin perjuicio de lo previsto en la normativa vigente.","doce meses de privación de libertad.","tres meses de privación de libertad.","cuatro meses de privación de libertad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cuatro meses de privación de libertad</mark></span><span class=\"ref-norma\">Art.  37 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"con el fin de proceder al cumplimiento de una condena a una pena o una medida de seguridad no inferior a cuatro meses de privación de libertad\"</span>Para cumplimiento de condena: no inferior a cuatro meses."}]},{"a":"Artículo 54 R22","q":[{"i":"21-ia-1718","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. La orden europea de detención y entrega se tramitará y ejecutará:","o":["con carácter preferente.","con carácter reservado.","con carácter prioritario y gratuito.","con carácter de urgencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">con carácter de urgencia</mark></span><span class=\"ref-norma\">Art.  54 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"La orden europea de detención y entrega se tramitará y ejecutará con carácter de urgencia\"</span>Se tramita y ejecuta con carácter de urgencia."},{"i":"21-148","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. Si la persona reclamada consiente la entrega, la resolución judicial deberá adoptarse:","o":["En los sesenta días siguientes a la celebración de la audiencia.","En los treinta días siguientes a la celebración de la audiencia.","En los diez días siguientes a la celebración de la audiencia.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En los diez días siguientes a la celebración de la audiencia</mark></span><span class=\"ref-norma\">Art. 54 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"Si la persona reclamada consiente la entrega, la resolución judicial deberá adoptarse en los diez días siguientes a la celebración de la audiencia\"</span>"},{"i":"21-51","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. Si la persona reclamada NO consiente la entrega, el plazo máximo para adoptar una resolución firme será:","o":["Sesenta días desde que se produjera la detención.","Cuarenta días desde que se produjera la detención.","Veinte días desde que se produjera la detención.","Ninguna opción es correcta"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Sesenta días desde que se produjera la detención</mark></span><span class=\"ref-norma\">Art. 54 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"Si no media consentimiento, el plazo máximo para adoptar una resolución firme será de sesenta días desde que se produjera la detención\"</span>Si la persona consiente la entrega, la resolución se adopta en diez días desde la audiencia; si no consiente, en sesenta días desde la detención."},{"i":"21-ia-1719","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. Cuando por razones justificadas no se pueda adoptar la decisión sobre la ejecución de la orden en los plazos señalados, éstos podrán prorrogarse por:","o":["otros diez días.","otros sesenta días, en los términos que se determinen reglamentariamente.","otros treinta días.","otros quince días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">otros treinta días</mark></span><span class=\"ref-norma\">Art.  54 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"éstos podrán prorrogarse por otros treinta días\"</span>La prórroga es de otros treinta días."},{"i":"21-ia-1720","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. Cuando por razones justificadas se prorroguen los plazos para adoptar la decisión sobre la orden, se comunicará a la autoridad judicial de emisión tal circunstancia y sus motivos y:","o":["se suspenderán los plazos de la detención.","se mantendrán entretanto las condiciones necesarias para la entrega.","se pondrá en libertad provisional a la persona reclamada, salvo que la autoridad judicial disponga otra cosa.","se solicitará autorización al Ministerio de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se mantendrán entretanto las condiciones necesarias para la entrega</mark></span><span class=\"ref-norma\">Art.  54 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"se mantendrán entretanto las condiciones necesarias para la entrega\"</span>Se mantienen las condiciones necesarias para la entrega."}]},{"a":"Artículo 86 ✱","q":[{"i":"21-182","p":"Convenio de Viena de 24 de abril de 1963, sobre Relaciones Consulares. ¿Qué determina el orden de precedencia de los jefes de oficina consular?","o":["Su antigüedad en el servicio.","La importancia de su país de origen.","El tamaño de la circunscripción consular que dirigen.","La fecha de concesión del exequátur."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La fecha de concesión del exequátur</mark></span><span class=\"ref-norma\">Art. 16 · Convenio de Viena de 24 de abril de 1963, sobre Relaciones Consulares</span><span class=\"ref-concepto\">\"estará determinado, en su respectiva categoría, por la fecha de concesión del exequátur\"</span>"},{"i":"21-ia-1914","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. El Juez Central de Vigilancia Penitenciaria será la única autoridad competente para determinar el procedimiento de ejecución y las medidas conexas a adoptar, incluida:","o":["la eventual adaptación de la condena.","la eventual retirada del certificado.","la eventual devolución de la resolución, en los términos que se determinen reglamentariamente.","la eventual concesión de la libertad condicional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la eventual concesión de la libertad condicional</mark></span><span class=\"ref-norma\">Art.  86 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"incluida la eventual concesión de la libertad condicional\"</span>Incluye la eventual concesión de la libertad condicional."},{"i":"21-ia-3022","p":"Convenio de Viena de 24 de abril de 1963, sobre Relaciones Consulares. El orden de precedencia de los Jefes de oficina consular estará determinado, en su respectiva categoría, por:","o":["la fecha de presentación de la carta patente.","el orden alfabético de los Estados que envían.","la antigüedad de las relaciones consulares.","la fecha de concesión del exequátur."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la fecha de concesión del exequátur</mark></span><span class=\"ref-norma\">Art.  16 · Convenio de Viena de 24 de abril de 1963, sobre Relaciones Consulares</span><span class=\"ref-concepto\">\"estará determinado, en su respectiva categoria, por la fecha de concesión del exequátur\"</span>Se determina por la fecha de concesión del exequátur."}]},{"a":"Artículo 96","q":[{"i":"21-ia-1930","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. Son requisitos para que la autoridad judicial española emita a otro Estado miembro una resolución de libertad vigilada. Señale la INCORRECTA:","o":["Que se haya dictado una resolución judicial firme de libertad vigilada.","Que el condenado no tenga su residencia legal y habitual en España.","Que haya regresado al Estado donde reside legal y habitualmente o que, aun estando en nuestro país, haya manifestado su voluntad de regresar a éste o a otro Estado miembro que lo autorice.","Que el condenado tenga su residencia legal y habitual en España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Que el condenado tenga su residencia legal y habitual en España</mark></span><span class=\"ref-norma\">Art.  96 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"b) Que el condenado no tenga su residencia legal y habitual en España\"</span>Se exige que el condenado NO tenga su residencia legal y habitual en España."}]},{"a":"Artículo 137 ✱","q":[{"i":"21-2","p":"Ley 23/2014, de reconocimiento mutuo de resoluciones penales en la Unión Europea. La prórroga, revisión, modificación, revocación y anulación de la medida de protección y de la orden europea de protección emitida por España, será competencia:","o":["Compartida de la autoridad judicial española y de la autoridad competente del Estado de ejecución","Exclusiva de la autoridad judicial española que haya emitido la orden","De la autoridad competente del Estado de ejecución","Todas son incorrectas"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Exclusiva de la autoridad judicial española que haya emitido la orden</mark></span><span class=\"ref-norma\">Art. 137 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"a) La prórroga, revisión, modificación, revocación y anulación de la medida de protección y de la orden europea de protección\"</span>La competencia es exclusiva de la autoridad judicial española que emitió la orden, no compartida con el Estado de ejecución."},{"i":"21-ia-2110","p":"Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea. La autoridad judicial española que haya emitido la orden europea de protección tendrá competencia exclusiva para adoptar las resoluciones relativas a:","o":["la ejecución de la medida de protección en el Estado de ejecución.","la adaptación de la medida de protección al ordenamiento del Estado de ejecución, en los términos que se determinen reglamentariamente.","las sanciones por el incumplimiento de la medida en el Estado de ejecución.","la prórroga, revisión, modificación, revocación y anulación de la medida de protección y de la orden europea de protección."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la prórroga, revisión, modificación, revocación y anulación de la medida de protección y de la orden europea de protección</mark></span><span class=\"ref-norma\">Art.  137 · Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea</span><span class=\"ref-concepto\">\"tendrá competencia exclusiva para adoptar, de acuerdo con lo dispuesto en el ordenamiento jurídico español, las resoluciones relativas a: a) La prórroga, revisión, modificación, revocación y anulación de la medida de protección y de la orden europea de protección\"</span>La competencia exclusiva abarca prórroga, revisión, modificación, revocación y anulación."}]},{"a":"Artículo 8 R31","q":[{"i":"21-223","p":"Ley 4/2015, de 27 de abril, del Estatuto de la Víctima del Delito. Los Abogados y Procuradores no podrán dirigirse a las víctimas directas o indirectas de catástrofes, calamidades públicas u otros sucesos que hubieran producido un número elevado de víctimas que cumplan los requisitos que se determinen ______ y que puedan constituir delito, para ofrecerles sus servicios profesionales hasta transcurridos 45 días desde el hecho.","o":["Mediante Ley Orgánica.","Mediante Real Decreto.","Mediante Ley Ordinaria.","Reglamentariamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Reglamentariamente.</mark></span>El Estatuto de la Víctima establece que estos requisitos se determinarán reglamentariamente."},{"i":"21-55","p":"Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito. Los Abogados y Procuradores no podrán dirigirse a las víctimas directas o indirectas de catástrofes, calamidades públicas u otros sucesos que hubieran producido un número elevado de víctimas que cumplan los requisitos que se determinen reglamentariamente y que puedan constituir delito, para ofrecerles sus servicios profesionales:","o":["Hasta transcurridos 20 días desde el suceso.","Hasta transcurridos 30 días desde el suceso.","Hasta transcurridos 45 días desde el hecho.","Hasta transcurridos 60 días desde el hecho."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Hasta transcurridos 45 días desde el hecho</mark></span><span class=\"ref-norma\">Art. 8 · Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito</span><span class=\"ref-concepto\">\"para ofrecerles sus servicios profesionales hasta transcurridos 45 días desde el hecho\"</span>"},{"i":"21-189","p":"Ley 4/2015, de 27 de abril, del Estatuto de la Víctima del Delito. ¿Cuántos días deben transcurrir para que Abogados y Procuradores puedan ofrecer sus servicios profesionales a las víctimas de catástrofes o calamidades públicas?","o":["15 días desde el hecho.","30 días desde el hecho.","45 días desde el hecho.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">45 días desde el hecho</mark></span><span class=\"ref-norma\">Art. 8 · Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito</span><span class=\"ref-concepto\">\"para ofrecerles sus servicios profesionales hasta transcurridos 45 días desde el hecho\"</span>"},{"i":"21-ia-2632","p":"Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito. La prohibición de dirigirse a las víctimas durante el período de reflexión quedará sin efecto en el caso de que:","o":["la víctima haya presentado denuncia, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","la prestación de estos servicios profesionales haya sido solicitada expresamente por la víctima.","el Colegio de Abogados lo autorice.","el Juez de Instrucción lo autorice."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la prestación de estos servicios profesionales haya sido solicitada expresamente por la víctima</mark></span><span class=\"ref-norma\">Art.  8 · Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito</span><span class=\"ref-concepto\">\"Esta prohibición quedará sin efecto en el caso de que la prestación de estos servicios profesionales haya sido solicitada expresamente por la víctima\"</span>Queda sin efecto si la víctima solicita expresamente los servicios."},{"i":"21-ia-2631","p":"Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito. Los Abogados y Procuradores no podrán dirigirse a las víctimas directas o indirectas de catástrofes, calamidades públicas u otros sucesos que hubieran producido un número elevado de víctimas para ofrecerles sus servicios profesionales hasta transcurridos 45 días desde el hecho. El incumplimiento de esta prohibición dará lugar a:","o":["responsabilidad disciplinaria por infracción grave, sin perjuicio de las demás responsabilidades, sin perjuicio de lo previsto en la normativa vigente.","responsabilidad penal por delito de intrusismo.","responsabilidad disciplinaria por infracción muy grave, sin perjuicio de las demás responsabilidades que procedan.","responsabilidad civil por los daños ocasionados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">responsabilidad disciplinaria por infracción muy grave, sin perjuicio de las demás responsabilidades que procedan</mark></span><span class=\"ref-norma\">Art.  8 · Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito</span><span class=\"ref-concepto\">\"El incumplimiento de esta prohibición dará lugar a responsabilidad disciplinaria por infracción muy grave, sin perjuicio de las demás responsabilidades que procedan\"</span>Es infracción muy grave."}]},{"a":"Artículo 10 R32","q":[{"i":"21-143","p":"Ley 4/2015, de 27 de abril, del estatuto de la víctima del delito. Toda víctima tiene derecho a acceder, de forma ______ en los términos que reglamentariamente se determine, a los servicios de asistencia y apoyo facilitados por las Administraciones públicas, así como a los que presten las Oficinas de Asistencia a las Víctimas.","o":["Directa y pública.","Gratuita y confidencial.","Limitada y próxima.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Gratuita y confidencial</mark></span><span class=\"ref-norma\">Art. 10 · Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito</span><span class=\"ref-concepto\">\"Toda víctima tiene derecho a acceder, de forma gratuita y confidencial, en los términos que reglamentariamente se determine, a los servicios de asistencia y apoyo\"</span>"},{"i":"21-ia-2636","p":"Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito. Toda víctima tiene derecho a acceder, de forma gratuita y confidencial, en los términos que reglamentariamente se determine, a los servicios de asistencia y apoyo facilitados por las Administraciones públicas, así como a los que presten las Oficinas de Asistencia a las Víctimas. Este derecho podrá extenderse a los familiares de la víctima cuando se trate de:","o":["delitos contra la vida.","delitos que hayan causado perjuicios de especial gravedad.","delitos cometidos contra menores, sin perjuicio de lo previsto en la normativa vigente.","delitos de violencia de género."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">delitos que hayan causado perjuicios de especial gravedad</mark></span><span class=\"ref-norma\">Art.  10 · Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito</span><span class=\"ref-concepto\">\"Este derecho podrá extenderse a los familiares de la víctima, en los términos que asimismo se establezcan reglamentariamente, cuando se trate de delitos que hayan causado perjuicios de especial gravedad\"</span>Se extiende a familiares en delitos con perjuicios de especial gravedad."},{"i":"21-ia-2637","p":"Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito. Las autoridades o funcionarios que entren en contacto con las víctimas deberán derivarlas a las Oficinas de Asistencia a las Víctimas cuando resulte necesario en atención a la gravedad del delito o en aquellos casos en los que:","o":["la víctima lo solicite.","el Ministerio Fiscal lo ordene.","el Juez lo acuerde de oficio.","la víctima sea menor de edad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la víctima lo solicite</mark></span><span class=\"ref-norma\">Art.  10 · Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito</span><span class=\"ref-concepto\">\"o en aquellos casos en los que la víctima lo solicite\"</span>También cuando la víctima lo solicite."}]}];
